                var ownerFn = wmScheduleOwnerFn();
                if (typeof LD2_SUP_SCHEDULE_CREATE === 'undefined' || typeof LD2_ROLE_SCHEDULE_CREATE === 'undefined' || !ownerFn)
                    return LD2_CAN_SCHEDULE_CREATE !== false;
                return !!(LD2_SUP_SCHEDULE_CREATE || (LD2_ROLE_SCHEDULE_CREATE && ownerFn()));
